package com.example.complaintmanagement.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final CustomUserDetailsService uds; public JwtAuthenticationFilter(JwtService j,CustomUserDetailsService u){jwt=j;uds=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain f)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){try{String u=jwt.username(t);UserDetails d=uds.loadUserByUsername(u);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}} f.doFilter(r,s);} }
